def execute(arguments):
    """
    文件比较

    参数:
        arguments (dict): 包含以下字段
            - path1 (str): 第一个文件/目录路径，必填
            - path2 (str): 第二个文件/目录路径，必填
            - compare_content (bool): 是否比较文件内容，默认 True
            - ignore_whitespace (bool): 是否忽略空白字符差异，默认 False

    返回:
        dict: 包含比较结果的字典
            - success (bool): 是否成功
            - identical (bool): 是否完全相同
            - differences (list): 差异列表
            - path1 (str): 第一个路径
            - path2 (str): 第二个路径
            - error (str): 错误信息（失败时）
    """
    import os
    import hashlib

    path1 = arguments.get("path1", "")
    path2 = arguments.get("path2", "")
    compare_content = arguments.get("compare_content", True)
    ignore_whitespace = arguments.get("ignore_whitespace", False)

    if not path1 or not path2:
        return {"success": False, "error": "请提供两个文件/目录路径"}

    if not os.path.exists(path1):
        return {"success": False, "error": f"路径不存在: {path1}"}

    if not os.path.exists(path2):
        return {"success": False, "error": f"路径不存在: {path2}"}

    def get_file_hash(path):
        hasher = hashlib.md5()
        with open(path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b""):
                hasher.update(chunk)
        return hasher.hexdigest()

    try:
        differences = []

        if os.path.isfile(path1) and os.path.isfile(path2):
            if compare_content:
                if ignore_whitespace:
                    with open(path1, 'r') as f1, open(path2, 'r') as f2:
                        content1 = ''.join(f1.read().split())
                        content2 = ''.join(f2.read().split())
                    identical = content1 == content2
                else:
                    hash1 = get_file_hash(path1)
                    hash2 = get_file_hash(path2)
                    identical = hash1 == hash2
            else:
                size1 = os.path.getsize(path1)
                size2 = os.path.getsize(path2)
                identical = size1 == size2

            if not identical:
                differences.append({
                    "type": "file_content",
                    "path1": path1,
                    "path2": path2
                })

        elif os.path.isdir(path1) and os.path.isdir(path2):
            files1 = set()
            files2 = set()

            for root, dirs, files in os.walk(path1):
                for f in files:
                    rel_path = os.path.relpath(os.path.join(root, f), path1)
                    files1.add(rel_path)

            for root, dirs, files in os.walk(path2):
                for f in files:
                    rel_path = os.path.relpath(os.path.join(root, f), path2)
                    files2.add(rel_path)

            only_in_1 = files1 - files2
            only_in_2 = files2 - files1
            common = files1 & files2

            for f in only_in_1:
                differences.append({"type": "only_in_path1", "file": f})

            for f in only_in_2:
                differences.append({"type": "only_in_path2", "file": f})

            if compare_content:
                for f in common:
                    file1 = os.path.join(path1, f)
                    file2 = os.path.join(path2, f)
                    if get_file_hash(file1) != get_file_hash(file2):
                        differences.append({"type": "content_differs", "file": f})

            identical = len(differences) == 0

        else:
            return {
                "success": True,
                "identical": False,
                "differences": [{"type": "type_mismatch", "path1": path1, "path2": path2}]
            }

        return {
            "success": True,
            "identical": identical,
            "differences": differences,
            "path1": path1,
            "path2": path2
        }
    except Exception as e:
        return {"success": False, "error": f"比较失败: {str(e)}"}
